export default function postFetch({index,url,formdata,Post}){
    const _$ = window.$
    const _layer = window.layer;
    let index1 = _layer.load(1, {
        shade: [0.1, '#fff']
    });
    _$.ajax({
        type: "POST",
        url: url,
        data: formdata,
        dataType: "JSON",
        timeout: 5000,
        async: true,
        success: function (data) {
            if (data.status === 1) {
                Post(data.id);

                _layer.alert('添加成功', {
                    icon: 1
                    , closeBtn: 0
                });
            } else {
                _layer.alert(data.msg, {
                    closeBtn: 0
                    , icon: 7
                });
            }
        },
        error: function (e) {
            _layer.alert('添加失败', {
                closeBtn: 0
                , icon: 5
            });
        },
        complete:function(xhr,status){
            if(status === 'timeout'){
                _layer.alert('添加超时', {
                    closeBtn: 0,
                    icon:7
                });
            }
            _layer.close(index);
            _layer.close(index1);
        }
    });
}
