import React from 'react';

export default function NavSwitch() {
    let oBtn = document.querySelector("#btn");
    let oTc = document.querySelector(".tc");
    let oNav = document.querySelector("#wrap");

    // 点击显示nav
    function navShow(){
        oBtn.style.transform = "scale(0)";
        oTc.style.display = "block";
        oNav.style.transform = "translateX(0px)";
    }

    // 点击隐藏nav
    function navHide(){
        oBtn.style.transform = "scale(1)";
        oTc.style.display = "none";
        oNav.style.transform = "";
    }

    return (
        <div className="NavSwitch">
            <button id="btn" onClick={navShow.bind(this)}>＞</button>
            <div className="tc" onClick={navHide.bind(this)}></div>
        </div>
    )
}