// import React, { useEffect } from 'react';
import rePut from '../Request/rePut'

export default function Header(props) {
    let { prod,projected,projectedata,inProject,cn } = props
    const layer = window.layer
    const $ = window.$

    // 点击主题回到首页
    function comeHome(){
        // 跳转主页并更新视图
        window.location.hash = '';
        projectedata = projected[0];
        prod = projected[0].id;
        cn({projected,projectedata,punt:1,prod});
        
        // 展开默认导航及改变color
        let oLink = document.querySelectorAll("#wrap a");
        let oDl = document.querySelectorAll("#wrap dl");
        for(let i = 0;i<oLink.length;i++){
            oLink[i].classList.remove("active");
            if(i<oDl.length && i !== 0){
                oDl[i].style.height = '0px';
            }
        }
        let oLi = document.querySelector("#project" + prod);
        if(oLi){
            oLi.querySelector("dl").style.height = "100px";
            oLi.querySelector("a").classList.add("active");
        }else{
            document.querySelectorAll("#wrap a")[0].classList.add("active");
            document.querySelectorAll("#wrap dl")[0].style.height = "100px";
        }
    }

    // 头部点击弹出
    function out(message,adress){
        if(adress === 2){
            adress = $(".app2")
        }else if(adress === 3){
            adress = $(".app3")
        }else if(adress === 4){
            adress = $(".app4")
        }else{
            adress = $(".app1")
        }
        layer.tips(message, adress, {
            tips: [1, '#3595CC'],
            time: 3000
        });

    }

    //修改项目
    function editProject() {
        inProject({
            title: '编辑项目信息',
            success:function(){
                $(".delete").css("display","block");
                $(".proWindow").css("padding-top","0px");
                $("#myproject input").removeAttr("style");
                let oInp = document.querySelectorAll("#myproject input");
                for (let key in projectedata) {
                    // 遍历输入框
                    for (let j = 0; j < oInp.length; j++) {
                        if (key === oInp[j].name) {
                            oInp[j].value = projectedata[key];
                        }
                    }
                }
                $("#proImg").css("display","block");
                $("#proImg").attr("src",$("#pro5").val());
            },
            change:function(index,formdata){
                rePut({
                    index,
                    url:'https://licat.work/page_center/project/' + projectedata.id,
                    formdata,
                    Put:function(){
                        // 找到项目集合中的目标对象修改
                        for(let i = 0;i<projected.length;i++){
                            if(projected[i].id === prod){
                                formdata['id'] = prod;
                                projected[i] = formdata;
                            }
                        }
                        // 修改个体项目
                        projectedata = formdata;
                        // 调用父组件更新视图
                        cn({projected,projectedata})
                    }
                })
            }
        })
    }

    return projectedata &&(
        <div className="top">
            <div className="title" onClick={comeHome}>享购页面管理中心</div>
            <ul id={'top'}>
                <li className="app1" onClick={(window.userpower&&window.userpower===7)?editProject:out.bind(this,projectedata.name,1)}>
                    <img src={projectedata.gravatar} alt=""/>
                    <span>{projectedata.teacher}</span>
                </li>
                <li className="app4" onClick={out.bind(this,projectedata.office,4)}>办公地点</li>
                <li className="app3" onClick={out.bind(this,projectedata.keywords,3)}>关键词</li>
                <li className="app2" onClick={out.bind(this,projectedata.description,2)}>简介</li>
            </ul>
        </div>
    )
}