import React from 'react';
// import rePhoto from '../Request/rePhoto';

export default function LandWindow(props) {
    const {pageview,page,deletePage,pageChange,} = props;
    // 上传图片
    // function upload(e){
    //     let file = e.target.files[0];
    //     // let punt = 1;
    //     rePhoto(file);
    // }

    return (
        <div className="LandWindow pageWindow">
            <button className="delete" onClick={deletePage.bind(this,pageChange)}>删除页面</button>
            <form action="" id="landingform" autoComplete="off" className="pageform">
                <div className="formhead">发布日期:</div>
                <input type='date' id= 'ss1' name='releasedate' placeholder='输入发布日期' />
                <br />
                <div className="formhead">作 者:</div>
                <input type='text' id='ss2' name='author' placeholder='输入作者' />
                <br />
                <div className="formhead">标 题:</div>
                <input type='text' id= 'ss4' name='title' placeholder='输入页面标题' />
                <br />
                <div className="formhead">描 述:</div>
                <input type='text' id= 'ss6' name='description' placeholder='输入页面描述' />
                <br />
                <div className="formhead dm">网页源码:</div>
                <textarea type='text' id= 'ss8' name='html' placeholder='输入html代码' onClick={pageview.bind(this,page)}></textarea>  
                <div id='ss9'>
                    <div className='mediu'>
                        <div className='phh'>
                            <span>+</span>
                            {/* <input accept="image/png, image/jpeg, image/gif, image/jpg" type='file' id='tp' onChange={upload.bind(this)} className='pho' name='photo' /> */}
                        </div>
                        <img className='ppp' id='preImg' src='#' alt='' />
                    </div>
                    <div className="biao">
                        <p>图片大小<br />＜＝500KB</p>
                        <p>图片尺寸<br />＞=320*568</p>
                    </div>
                </div>
                <div className="formhead">图片路径:</div>
                <input type='text' id='ss5' name='screenshot' placeholder='输入图片路径'/>
                <br />
                <div className="formhead dm">加密代码:</div>
                <textarea type='text' id= 'eninput' name='safehtml' placeholder='输入加密代码' onClick={pageview.bind(this,page)}></textarea>   
            </form>
            <div id='ss3' className="single">
                <div className="formhead">评级:</div>
                <div className="label_box">
                    <label>
                        <input type="radio" name="grade" value='A' />
                        <div>A</div>
                    </label>
                    <label>
                        <input type="radio" name="grade" value='B' />
                        <div>B</div>
                    </label>
                    <label>
                        <input type="radio" name="grade" value='C' />
                        <div>C</div>
                    </label>
                    <label>
                        <input type="radio" name="grade" value='D' />
                        <div>D</div>
                    </label>
                </div>
            </div>
            <div id='ss7' className="single young">
                <div className="formhead fb">发布状态:</div>
                <div className="label_box">
                    <label>
                        <input type="radio" name="status" defaultValue="0" />
                        <div>未发布</div>
                    </label>
                    <label>
                        <input type="radio" name="status" defaultValue="1" />
                        <div>已发布</div>
                    </label>
                </div>
            </div>
        </div>
    )
}