export default function unit(callbackfn) {
  const _layer = window.layer;
  const html2canvas = window.html2canvas;
  const _$ = window.$;
  // 截取子页面iframe
  // window.child.parseUri = function (c) {
  //     var b = /^(?:([^:\/?#]+):)?(?:\/\/([^\/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?/;
  //     var a = c.match(b);
  //     if (a) {
  //         return {
  //             scheme: a[1],
  //             host: a[2],
  //             path: a[3],
  //             query: a[4],
  //             fragment: a[5],
  //         };
  //     } else {
  //         return null;
  //     }
  // }
  window.child.getBase64 = function (imgUrl, callback) {
    window.URL = window.URL || window.webkitURL;
    var xhr = new XMLHttpRequest();
    xhr.open("get", imgUrl, true);
    xhr.responseType = "blob";
    xhr.onload = function () {
      if (this.status === 200) {
        var blob = this.response;
        let oFileReader = new FileReader();
        oFileReader.onloadend = function (e) {
          let base64 = e.target.result;
          callback(base64);
        };
        oFileReader.readAsDataURL(blob);
        // let src = window.URL.createObjectURL(blob);
      } else {
        callback(null);
      }
    };
    xhr.send();
  };
  window.child.base64screen = function () {
    let allImgE = this.document.body.querySelectorAll("img");
    if (allImgE.length === 0) {
      this.getscreen();
      return;
    }
    let imgContainer = [];
    allImgE.forEach((value, key) => {
      // if (this.parseUri(value.src).host !== this.location.host) {
      imgContainer.push(value);
      // }
    });
    let allImgLen = imgContainer.length;
    let lenMark = 0;

    imgContainer.forEach((item) => {
      if (item.dataset.show === "show") {
        let imgurl = item.getAttribute("licat-url") || item.src;

        this.getBase64(imgurl, (canvas) => {
          if (canvas) {
            item.src = canvas;
          }
          lenMark++;
        });
      } else {
        lenMark++;
      }
    });
    let timer = null;
    timer = setInterval(() => {
      if (lenMark === allImgLen) {
        clearInterval(timer);
        this.getscreen();
      }
    });
  };

  function dataURLtoFile(dataurl, filename) {
    var arr = dataurl.split(","),
      mime = arr[0].match(/:(.*?);/)[1],
      bstr = atob(arr[1]),
      n = bstr.length,
      u8arr = new Uint8Array(n);
    while (n--) {
      u8arr[n] = bstr.charCodeAt(n);
    }
    return new File([u8arr], filename, { type: mime });
  }

  window.child.getscreen = function () {
    let index = _layer.msg("正在截取图片...", {
      icon: 16,
      time: 0,
    });
    html2canvas(this.document.body, {
      width: 320,
      height: 568,
    })
      .then(function (canvas) {
        //结果处理
        var myImage = canvas.toDataURL("image/png");
        var imgfile = dataURLtoFile(myImage,"screenimg");
        _$("#preImg").attr("src", myImage);
        _$("#preImg").css("display", "block");
        _$("#ss5").val(myImage);
        _$("#ppImg").attr("src", myImage);
        _$("#ppImg").css("display", "block");
        _$("#ll5").val("");

        _layer.close(index);
        _layer.msg("截图成功", {
          time: 1500,
          icon: 1,
        });
        callbackfn(imgfile);
      })
      .catch((error) => {
        _layer.close(index);
        if (error === "timeout") {
          window.top._layer.msg("网络较慢，请刷新后再尝试", {
            time: 1500,
            icon: 7,
          });
        } else {
          _layer.msg("截图失败:" + error, {
            time: 1500,
            icon: 5,
          });
        }
      });
  };
  window.child.ShowImgHandle = function () {
    this.document.body.scrollTop = 0;
    this.document.documentElement.scrollTop = 0;
    const io = new IntersectionObserver(callback);
    function callback(entries) {
      entries.forEach((item, key) => {
        if (item.isIntersecting) {
          item.target.dataset.show = "show";
        } else {
          item.target.dataset.show = "hide";
        }
      });
      window.child.base64screen();
    }
    this.document.body.querySelectorAll("img").forEach((item) => {
      io.observe(item);
    });
  };
  window.child.ShowImgHandle();
}
