// 图片上传
export default  function uploade(imgfile){
    const _layer = window.layer
    const $ = window.$
    // 获取图片文件
    let file = imgfile;
    // if(punt === 1){
    //     file = $("#ss9 .pho")[0]
    // }else if(punt === 0){
    //     file = $("#ll9 .pho")[0]
    // }

    // if (!file.files || !file.files[0]) return;

    // 限制图片大小
    if(file.size>(500*1024)){
        _layer.alert('图片大小超过500K', {
            icon: 7
            , closeBtn: 0
        });
        return
    }
    let reader = new FileReader();
    var formData = new FormData();
    formData.append('photo', file);
    reader.onload = function (evt) {
        // 限制图片分辨率
        let image = new Image();
        image.src = evt.target.result;
        image.onload = function(){
            if(this.width < 320 || this.height < 568){
                _layer.alert('图片尺寸最小为 320*568', {
                    icon: 7
                    , closeBtn: 0
                });
            }else{
                // if(punt === 1){
                //     document.getElementById("preImg").src = evt.target.result;
                //     document.getElementById("preImg").style.display = "block";
                // }else{
                //     document.getElementById("ppImg").src = evt.target.result;
                //     document.getElementById("ppImg").style.display = "block";
                // }
                let index = _layer.load(1, {
                    shade: [0.1, '#fff']
                });
                $.ajax({
                    type: "POST",
                    url: "https://licat.work/page_center/uploadimg",
                    data: formData,
                    contentType: false,
                    timeout: 5000,
                    async: true,            
                    processData: false,
                    success: function (data) {
                        if (data.status === 1) {
                            _layer.alert('上传成功', {
                                closeBtn: 0
                                , icon: 1
                            });
                            _layer.close(index);
                            if($("#ll5")[0].offsetTop!==0){
                                $("#ll5").val(data.src)
                            }else{
                                $("#ss5").val(data.src);
                            }
                            // if(punt === 1){
                            //     $("#ss5").val(data.src);
                            // }else{
                            //     $("#ll5").val(data.src)
                            // }
                        } else {
                            _layer.alert(data.msg, {
                                closeBtn: 0
                                , icon: 7
                            });
                            _layer.close(index);
                        }
                    },
                    error: function (e) {
                        console.log(e);
                        _layer.alert('上传失败', {
                            closeBtn: 0
                            , icon: 5
                        });
                        _layer.close(index);
                    },
                    complete:function(xhr,status){
                        if(status === 'timeout'){
                            _layer.alert('上传超时', {
                                closeBtn: 0,
                                icon: 7
                            });
                            _layer.close(index);
                        }
                    }
                });
            }
        }
    }
    reader.readAsDataURL(file);
}