import React from 'react';
// import { withRouter } from 'react-router-dom';
import reDelete from '../Request/reDelete'


function proWindow(props) {
    const _layer = window.layer;
    let {prod,projected,projectedata,cn} = props

    // 删除项目
    function deleteProject(){
        _layer.confirm('您确定要删除该项目吗？', {
            icon: 2,
            btn: ['确认', '取消'] //按钮
        }, function () {
            // 关闭页面信息弹窗
            _layer.closeAll('page');
            reDelete({
                url:'https://licat.work/page_center/project/'+ prod,
                Delete:function(){
                    for(let i = 0;i<projected.length;i++){
                        // 根据id找到项目集合中对应的项目删除
                        if(projected[i].id === prod){
                            projected.splice(i, 1); 
                            // 跳转到根页面
                            window.location.hash = '';
                            projectedata = projected[0];
                            prod = projected[0].id;
                            cn({projected,projectedata,punt:1,prod});

                            // 展开默认导航及改变color
                            let oLi = document.querySelector("#project" + prod);
                            if(oLi){
                                oLi.querySelector("dl").style.height = "100px";
                                oLi.querySelector("a").classList.add("active");
                            }else{
                                document.querySelectorAll("#wrap a")[0].classList.add("active");
                                document.querySelectorAll("#wrap dl")[0].style.height = "100px";
                            }
                            i = projected.length;
                        }
                    }
                }
            })
        })
    }

    // 头像上传
    function headload(){
        const $ = window.$
        const layer = window.layer
        // 获取图片文件
        let file = $("#pps .pho")[0]
        if (!file.files || !file.files[0]) return;

        // 限制图片大小
        if(file.files[0].size>(100*1024)){
            layer.alert('头像大小超过100K', {
                icon: 7
                , closeBtn: 0
            });
            return
        }
        let reader = new FileReader();
        var formData = new FormData();
        formData.append('photo', file.files[0]);
        reader.onload = function (evt) {

            // 限制图片分辨率
            let image = new Image();
            image.src = evt.target.result;
            // 图片加载
            image.onload = function(){
                if(this.width > 120 || this.height > 120){
                    layer.alert('头像尺寸最大为 120*120', {
                        icon: 7
                        , closeBtn: 0
                    });
                }else{
                    document.getElementById("proImg").src = evt.target.result;
                    document.getElementById("proImg").style.display = "block";
                    var index = layer.load(1, {
                        shade: [0.1, '#fff']
                    });
                    fetch('https://licat.work/page_center/uploadimg',{
                        method: "POST", // 请求方式
                        body: formData,	 // 请求体
                    })
                    .then(response => {
                        return response.json()
                    })
                    .then(data => {
                        if(data.status === 1){
                            layer.alert('上传成功', {
                                icon: 1
                                , closeBtn: 0
                            });
                            $("#pro5").val(data.src);
                        }else{
                            layer.alert(data.msg, {
                                icon: 7
                                , closeBtn: 0
                            });
                        }
                        layer.close(index);
                    })
                    .catch(error => {
                        console.log(error)
                        layer.alert('头像上传失败', {
                            icon: 5
                            , closeBtn: 0
                        });
                    })
                }
            }
        }
        reader.readAsDataURL(file.files[0]);
    };

    return (
        <div className="proWindow">
            <button className="delete" onClick={deleteProject.bind(this)}>删除项目</button>
            <form action="" id="myproject" autoComplete="off">
                <div className="formhead">项目名称:</div>
                <input type='text' id= 'pro1' className='layui-layer-input' name='name' placeholder='输入项目名称' />
                <br />
                <div className="formhead">指导老师:</div>
                <input type='text' id='pro2' className='layui-layer-input' name='teacher' placeholder='输入项目老师' />
                <br />
                <div className="formhead">描 述:</div>
                <input type='text' id= 'pro3' className='layui-layer-input' name='description' placeholder='输入项目描述' />
                <br />
                <div className="formhead">关键字:</div>
                <input type='text' id= 'pro4' className='layui-layer-input' name='keywords' placeholder='输入关键字' />
                <br />
                <div id='pps'>
                    <div className='mediu'>
                        <div className='phh'>
                            <span>+</span>
                            <input accept="image/png, image/jpeg, image/gif, image/jpg" type='file' id='tx' onChange={headload.bind(this)} className='layui-layer-input pho' name='photo' />
                        </div>
                        <img className='ppp' id="proImg" src='#' alt='' />
                    </div>
                    <div className="biao">
                        <p>图片大小<br />＜＝100KB</p>
                        <p>图片尺寸<br />＜＝120*120</p>
                    </div>
                </div>
                <div className="formhead">图片路径:</div>
                <input type='text' id= 'pro5' className='layui-layer-input' name='gravatar' placeholder='输入头像地址' />
                <br />
                <div className="formhead">办公地点:</div>
                <input type='text' id= 'pro6' className='layui-layer-input' name='office' placeholder='输入办公地点'/>
            </form>
        </div>
    )
}

export default proWindow;