// import { Link } from 'react-router-dom'
import rePost from '../Request/rePost';

export default function Nav(props) {
    const { projected,inProject,fn,gn,cn } = props;
    const _$ = window.$;

    // 添加项目
    function createProject(){
        inProject({
            title: '添加项目信息',
            btn: '提交',
            success:function(){
                // 隐藏删除键，调整样式，清空信息
                _$(".delete").css("display","none");
                _$(".proWindow").css("padding-top","10px");
                _$("#myproject input").removeAttr("style");
                let form = document.getElementById("myproject");
                let oInp = form.querySelectorAll("#myproject input");
                for(let i = 0; i<oInp.length;i++){
                    oInp[i].value ='';
                }
                _$("#proImg").css("display","none");
                _$("#proImg").attr("src","#");
            },
            change:function(index,formdata){
                rePost({
                    index,
                    url:'https://licat.work/page_center/project',
                    formdata,
                    Post:function(id){
                        // 添加后端返回的id
                        formdata['id'] = id;
                        // 添加新项目到项目集合
                        projected.push(formdata);
                        // 调用主页面重新渲染
                        cn({projected});
                    }
                })
            },
        })
    };

    // 阻止a标签默认跳转
    function preventJump(e){
        e.preventDefault();
    }

    return (
        <ul id="wrap">
            {
            projected && projected.map((item,index) => {
                return(
                    <li key={index} id={'project' + item.id}>    
                        <div onClick={gn.bind(this)} >{item.name}</div>
                        <dl>
                            {/* 点击改变项目ID以及页面名称 */}
                            <dd onClick={fn.bind(this,item.id,'landingpage')}>
                                <a href="/" onClick={preventJump}>落地页</a>
                            </dd>
                            <dd onClick={fn.bind(this,item.id,'auditpage')}>
                                <a href="/" onClick={preventJump}>审核页</a>
                            </dd>
                        </dl>
                    </li>
                )
            })
            }
            {(window.userpower&&window.userpower===7)?<li><div onClick={createProject.bind(this)}>+ 添加项目</div></li>:<></>}
        </ul>
    )
}