export default function deletedata({url,Delete}) {
    const _layer = window.layer;
    const $ = window.$;

    var index = _layer.load(1, {
        shade: [0.1, '#fff']
    });
    $.ajax({
        type: "POST",
        url: url,
        data: { _method: "DELETE" },
        dataType: "JSON",
        timeout: 5000,
        async: true,
        success: function (data) {
            if (data.status === 1) {
                //执行对state的操作以更新视图
                Delete();

                _layer.alert('删除成功', {
                    icon: 1
                    , closeBtn: 0
                });
                // 关闭页面信息弹窗
                _layer.closeAll('page');
            } else {
                _layer.alert(data.msg, {
                    closeBtn: 0
                    , icon: 7
                });
            }
        },
        error: function (error) {
            _layer.alert('删除失败', {
                closeBtn: 0
                , icon: 5
            });
            console.log(error);
        },
        complete:function(xhr,status){
            if(status === 'timeout'){
                _layer.alert('请求超时', {
                    closeBtn: 0,
                    icon:7
                });
            }
            _layer.close(index);
        }
    });
};