export default function getFetch(url,Getdata){
    const _layer = window.layer;
    const _$ = window.$;
    let index = _layer.load(1, {
        shade: 0
    });
    _$(".whiteTC").css("display","block");
    _$.ajax({
        type: "GET",
        url: url,
        timeout: 6000,
        async: true,
        success: function (result) {
            Getdata(result)
            _layer.close(index);
            _$(".whiteTC").css("display","none");
        },
        error: function (err) {
            _layer.alert('请求失败', {
                closeBtn: 0,
                icon: 5
            });
            _layer.close(index);
            _$(".whiteTC").css("display","none");
            console.log(err);
        },
        complete:function(xhr,status){
            if(status === 'timeout'){
                _layer.alert('请求超时，请刷新重试', {
                    closeBtn: 0,
                    icon: 7
                });
                _layer.close(index);
                _$(".whiteTC").css("display","none");
            }
        }
    });
}

