import React,{Fragment} from 'react';
// import { Route } from 'react-router-dom';
import rePost from '../Request/rePost';
import rePut from '../Request/rePut'
import reDate from '../Request/reDate'
import {compile} from '../Request/enhtml';


export default function Card(props) {
    const $ = window.$
    const { prod,page,pagedata,inLanding,inaudit,pageChange,cardClick } = props

    
    // 移动端点击显示编辑按钮
    function iShow(index,code){
        let oIframe = document.querySelectorAll(".cardui iframe");
        let oBack = document.querySelectorAll(".back");   
        let oEnter = document.querySelectorAll(".enter");
        let oEdit = document.querySelectorAll(".edit");

        const developjsCode = '<script>location.href = "about:srcdoc#development" </script>';
        // 移动端点击显示编辑按钮
        if(window.screen.width <= 750){
            if(!oEdit[index].isShow){
                oEdit[index].style.transform = "scale(1)";
                oEdit[index].isShow = 1;
            }else{
                oEdit[index].style.transform = "scale(0)";
                oEdit[index].isShow = 0;
            }
        }else{
            // PC端预览
            if(oIframe[index]){
                oIframe[index].setAttribute("srcdoc",code + developjsCode);
                oIframe[index].style.transform = "scale(1)";
                oBack[index].style.transform = "scale(1)";
                oEnter[index].style.transform = "scale(1)";
            }
        }
    }

    // PC点击关闭卡片预览
    function closeShow(index,e){
        e.stopPropagation();
        let oIframe = document.querySelectorAll(".cardui iframe");
        let oBack = document.querySelectorAll(".back");   
        let oEnter = document.querySelectorAll(".enter");

        oIframe[index].style.transform = "scale(0)";
        oBack[index].style.transform = "scale(0)";
        oEnter[index].style.transform = "scale(0)";
    }

    // 点击打开卡片新标签页面
    function pageJump(id,e){
        e.stopPropagation();
        window.open("https://licat.work/page_center/" + page + "/" + id + "/view")
    }

    // 添加落地页
    function createLanding(){
        inLanding({
            title:'添加',
            // 打开弹窗回调
            collect: function () {
                $(".delete").css("display","none");
                $(".LandWindow").css("padding-top","10px");
                $(".LandWindow input").removeAttr("style");
                // 清除文本信息
                let oInp = document.querySelectorAll("#landingform input,textarea");
                for(let i = 0; i<oInp.length;i++){
                    // 发布时间读取默认日期
                    if(oInp[i].name === 'releasedate'){
                        oInp[i].value = reDate();
                        i = i + 1;
                    }
                    oInp[i].value ='';
                }
                $("#preImg").attr("src","#");
                $("#preImg").css("display","none");
                $(".LandWindow input[type='radio']").prop('checked', false);
            },
            // 添加卡片
            change:function(index,formdata){
                rePost({
                    index,
                    url:'https://licat.work/page_center/landingpage',
                    formdata,
                    Post:function(id){
                        // 添加后端返回的id
                        formdata['id'] = id;
                        // 添加最后一次修改时间
                        formdata['lastupdate'] = reDate(1);
                        // 添加新页面到页面集合
                        pagedata.push(formdata);
                        // 调用页面重新渲染
                        pageChange({pagedata});
                    }
                })
            },
            // 传入卡片所属的项目id
            prod,
        })
    }

    // 修改落地页
    function editLanding(item,e) {
        e.stopPropagation();
        inLanding({
            title:'修改',
            // 获取卡片信息到弹窗
            collect: function (index) {
                $(".delete").css("display","block");
                $(".LandWindow").css("padding-top","0px");
                $(".LandWindow input").removeAttr("style");
                let form1 = document.getElementById("ss3");
                let form2 = document.getElementById("ss7");
                let oLab = form1.getElementsByTagName("input");
                let oLac = form2.getElementsByTagName("input");
                let oInp = document.querySelectorAll("#landingform input,textarea");
                cardClick({index});
                for (let key in item) {
                    // 单选框checked
                    for (let i = 0; i < oLab.length; i++) {
                        if (key === oLab[i].name) {
                            if (item[key] === oLab[i].value) {
                                oLab[i].checked = true;
                            }
                        }
                    }
                    for (let i = 0; i < oLac.length; i++) {
                        if (key === oLac[i].name) {
                            if (item[key] === Number(oLac[i].value)) {
                                oLac[i].checked = true;
                            }
                        }
                    }
                    // 遍历输入框
                    for (let i = 0; i < oInp.length; i++) {
                        if (key === oInp[i].name) {
                            oInp[i].value = item[key];
                        }
                        // 将html代码加密输出到表单
                        if(oInp[i].name === 'safehtml'){
                            oInp[i].value = compile(item['html'])
                        }
                    }
                };
                $("#preImg").css("display","block");
                $("#preImg").attr("src",$("#ss5").val());
                
            },
            // 修改卡片
            change: function (index,formdata) {
                rePut({
                    index,
                    url:"https://licat.work/page_center/landingpage/" + item.id,
                    formdata,
                    Put:function(){
                        // 添加最后一次修改时间
                        formdata['lastupdate'] = reDate(1);
                        // 找到页面集合中的目标对象修改
                        for(let i = 0;i<pagedata.length;i++){
                            if(pagedata[i].id === item.id){
                                pagedata[i] = formdata;
                            }
                        }
                        // 调用父组件更新视图
                        pageChange({pagedata})
                    }
                });
            },
            // 传入卡片id
            id: item.id,
            // 传入home组件更新视图方法
            pageChange,
        })
    }

    // 添加审核页
    function createAudit() {
        inaudit({
            title:'添加',
            // 清除弹窗信息
            collect:function(){
                $(".delete").css("display","none");
                $(".AuditWindow").css("padding-top","10px");
                $(".AuditWindow input").removeAttr("style");
                let oInp = document.querySelectorAll("#auditform input,textarea");
                for(let i = 0; i<oInp.length;i++){
                    // 发布时间默认为当前日期
                    if(oInp[i].name === 'releasedate'){
                        oInp[i].value = reDate();
                        i = i + 1;
                    }
                    oInp[i].value ='';
                }
                $("#ppImg").attr("src","#");
                $("#ppImg").css("display","none");
                $(".AuditWindow input[type='radio']").prop('checked', false);
            },
            // 添加卡片
            change:function(index,formdata){
                rePost({
                    index,
                    url:'https://licat.work/page_center/auditpage',
                    formdata,
                    Post:function(id){
                        // 添加后端返回的id
                        formdata['id'] = id;
                        // 添加最后一次修改时间
                        formdata['lastupdate'] = reDate(1);
                        // 添加新页面到页面集合
                        pagedata.push(formdata);
                        // 调用页面重新渲染
                        pageChange({pagedata});
                    }
                })
            },
            // 传入页面所属的项目id
            prod,
        })
    }

    // 修改审核页
    function editAudit(item,e){
        e.stopPropagation();
        inaudit({
            title: "修改",
            // 获取卡片信息到弹窗
            collect: function (index) {
                $(".delete").css("display","block");
                $(".AuditWindow input").removeAttr("style");
                $(".AuditWindow").css("padding-top","0px");
                $("#ppImg").css("display","none");
                // 将此弹窗的index传到删除方法中
                cardClick({index});
                let form = document.getElementById("ll7")
                let oLac = form.getElementsByTagName("input");
                let oInp = document.querySelectorAll("#auditform input,textarea");
                for (let key in item) {
                    // 单选框checked
                    for (let i = 0; i < oLac.length; i++) {
                        if (key === oLac[i].name) {
                            if (item[key] === Number(oLac[i].value)) {
                                oLac[i].checked = true;
                            }
                        }
                    }
                    // 遍历输入框
                    for (let i = 0; i < oInp.length; i++) {
                        if (key === oInp[i].name) {
                            oInp[i].value = item[key];
                        }
                    }
                };
                $("#ppImg").css("display","block");
                $("#ppImg").attr("src",$("#ll5").val());
            },
            // 修改卡片
            change:function(index,formdata){
                rePut({
                    index,
                    url:"https://licat.work/page_center/auditpage/" + item.id,
                    formdata,
                    Put:function(){
                        // 添加最后一次修改时间
                        formdata['lastupdate'] = reDate(1);
                        // 找到页面集合中的目标对象修改
                        for(let i = 0;i<pagedata.length;i++){
                            if(pagedata[i].id === item.id){
                                pagedata[i] = formdata;
                            }
                        }
                        // 调用父组件更新视图
                        pageChange({pagedata})
                    }
                });
            },
            // 传入卡片id
            id: item.id,
            // 传入home组件更新视图方法
            pageChange,
        })
    }

    // 卡片模板遍历
    function createCard(){
        if(pagedata){
            return pagedata.map((i,n)=>{
                // 落地页
                if( page === 'landingpage'){
                    return(
                        <div className="cardbox" key={n} onClick={iShow.bind(this,n,i.html)}>
                            <div className="cardui">
                                <div className="contain">
                                    <div className="cardphoto">
                                        <img src={i.screenshot} alt=""/>
                                    </div>
                                    <div className="leve">{i.grade}</div>
                                    <div className="all">
                                    <div>发布日期：{i.releasedate}</div>
                                    <div>修改日期：{i.lastupdate}</div>
                                    <div>作者：{i.author}</div>
                                    <div>简介：{i.description}</div>
                                    </div>
                                    <div className="cal">
                                        {i.status?"已发布":"未发布"}
                                    </div>
                                    {window.userpower&&window.userpower===7&&<button className="edit" onClick={(event) => { editLanding(i,event); cardClick({i,event});}}>✐</button>}
                                </div>
                                {/* UI预览图 */}
                                <iframe src="" frameBorder="0" title="card"></iframe>
                                <button className="back" onClick={closeShow.bind(this,n)}>↩</button>
                                <button className="enter" onClick={pageJump.bind(this,i.id)}>预览</button>
                            </div>
                        </div>
                    )
                }
                // 审核页
                else{
                    return(
                        <div className="cardbox" key={n} onClick={iShow.bind(this,n,i.html)}>
                            <div className="cardui">
                                <div className="contain">
                                    <div className="cardphoto">
                                        <img src={i.screenshot} alt=""/>
                                    </div>
                                    <div className="all">
                                        <div>发布日期：{i.releasedate}</div>
                                        <div>修改日期：{i.lastupdate}</div>
                                    </div>
                                    <div className="cal">
                                        {i.status?"已发布":"未发布"}
                                    </div>
                                    {window.userpower&&window.userpower===7&&<button className="edit" onClick={(event) => { editAudit(i,event); cardClick({i,event});}}>✐</button>}
                                </div>
                                {/* UI预览图 */}
                                <iframe src="" frameBorder="0" title="card"></iframe>
                                <button className="back" onClick={closeShow.bind(this,n)}>↩</button>
                                <button className="enter" onClick={pageJump.bind(this,i.id)}>预览</button>
                            </div>
                        </div>
                    )
                }
            })
        }
    };

    //遍历对应的router出口
    function projectHandle() {
        if( window.userpower&&window.userpower===7){
            if(page === 'landingpage'){
                return(
                    <Fragment>
                        {createCard()}
                        <div className="add" onClick={createLanding}>
                            <div className="lose1"></div>
                            <div className="lose2"></div>
                        </div>
                    </Fragment>
                )
            }else{
                return(
                    <Fragment>
                        {createCard()}
                        <div className="add" onClick={createAudit}>
                            <div className="lose1"></div>
                            <div className="lose2"></div>
                        </div>
                    </Fragment>
                )
            }
        }else{
            return(
                <Fragment>
                    {createCard()}
                </Fragment>
            )
        }
    }

    return (
        <div id="card">
            <div className="cardtain">
                {projectHandle()}
            </div>
            <div className="whiteTC"></div>
        </div>
    )
}
