export default function changedata({index,url, formdata,Put}) {
    const _layer = window.layer
    _layer.confirm('您确定要修改吗？', {
        icon: 3,
        btn: ['确认', '取消'] //按钮
    }, function () {
        let index1 = _layer.load(1, {
            shade: [0.1, '#fff']
        });
        // 序列化传递的参数
        function seque(obj) {
            var str = ["_method=put"];
            for (var p in obj) {
                str.push(encodeURIComponent(p) + "=" + encodeURIComponent(obj[p]));
            }
            return str.join("&");
        }
        var xhr = new XMLHttpRequest();
        xhr.open('POST', url, true);
        // 添加http头，发送信息至服务器时内容编码类型
        xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
        xhr.onreadystatechange = function () {
            if (xhr.readyState === 4) {
                if (xhr.status === 200 || xhr.status === 304) {
                    // let data = JSON.parse(xhr.responseText);
                    // 修改state更新视图
                    Put();

                    _layer.alert('修改成功', {
                        closeBtn: 0,
                        icon: 1
                    });
                    _layer.close(index1);
                    _layer.close(index);
                }
            } else {
                _layer.alert('修改失败', {
                    closeBtn: 0,
                    icon: 5
                });
                _layer.close(index1);
                _layer.close(index);
            }
        }
        // 超时设置
        xhr.timeout = 5000;
        xhr.ontimeout = function(){
            _layer.alert('修改超时', {
                closeBtn: 0,
                icon:7
            });
            _layer.close(index1);
            _layer.close(index);
        }
        xhr.send(seque(formdata));
    });
};