import Header from './Header'
import Nav from './Nav'
import Card from './Card'
import React, { Component } from 'react'
import ProWindow from '../Popup/ProWindow'
import LandWindow from '../Popup/LandWindow'
import AuditWindow from '../Popup/AuditWindow'
import CodeWindow from '../Popup/CodeWindow'
import NavSwitch from '../Popup/NavSwitch'

// 请求
import reGet from '../Request/reGet'
import reDelete from '../Request/reDelete'
import { compile, uncompile } from '../Request/enhtml'
import unit from '../Request/unit'
import rePhoto from '../Request/rePhoto';


class Home extends Component {
  // 总项目，项目id，页面名，页面数据
  constructor(props) {
    super(props)
    this.state = {
      // 项目id及页面名称
      prod: 1,
      page: '',
      // 总项目，项目，某页面集合,单页面数据，默认页面
      projected: [],
      projectedata: {},
      pagedata: [],
      onepage: {},
      // 二级菜单防抖识别
      timer: '',
    }
  }

  // 初始化请求
  componentDidMount() {
    // 请求加载数据
    reGet('https://licat.work/page_center/project', (data) => {
      this.setState({
        projected: data.data,
      })
      // 指定头部和页面（查询缓存）
      let result = data.data[0].id
      let name = 'landingpage'

      // 根据hash判断是否修改默认值
      if (window.location.hash.slice(1).split('&').length === 2) {
        let arry = window.location.hash.slice(1).split('&')
        if (parseInt(arry[0]).toString() !== 'NaN') {
          result = parseInt(arry[0])
          if (arry[1] === 'landingpage' || arry[1] === 'auditpage') {
            name = arry[1]
          }
        }
      }

      // 展开默认导航栏
      let oLi = document.querySelector('#project' + result)
      if (oLi) {
        oLi.querySelector('dl').style.height = '100px'
        if (name === 'landingpage') {
          oLi.querySelector('a').classList.add('active')
        } else {
          oLi.querySelectorAll('a')[1].classList.add('active')
        }
      } else {
        result = data.data[0].id
        name = 'landingpage'
        window.location.hash = result + '&' + name
        document
          .querySelector('#project' + result)
          .querySelector('dl').style.height = '100px'
        document
          .querySelector('#project' + result)
          .querySelector('a')
          .classList.add('active')
      }

      // 从项目集合中找到指定项目 (且更新prod)
      for (let i = 0; i < data.data.length; i++) {
        if (data.data[i].id === result) {
          this.setState({
            projectedata: data.data[i],
            prod: result,
          })
          i = data.data.length
        }
      }

      // 请求页面（且更新page）
      reGet(
        'https://licat.work/page_center/project/' + result + '/' + name,
        (pagedata) => {
          this.setState({
            pagedata: pagedata.data,
            page: name,
          })
        },
      )
    })
  }

  // 导航显示隐藏
  firstClick = (e) => {
    // 导航栏伸缩
    if (e.target.nextSibling.style.height === '100px') {
      e.target.nextSibling.style.height = '0px'
    } else {
      e.target.nextSibling.style.height = '100px'
    }
  }

  // 二级菜单点击更新
  projClick = (id, name, e) => {
    const _$ = window.$
    let { projected } = this.state

    // 改变color
    _$('#wrap a').removeClass('active')
    e.target.children[0] && e.target.children[0].classList.add('active')
    e.target.children[0] || e.target.classList.add('active')

    // 更改hash路由
    window.location.hash = id + '&' + name
    this.setState({
      prod: id,
      page: name,
      timer: id + name,
      pagedata: [],
    })

    // 在项目集合中找到指定项目
    for (let i = 0; i < projected.length; i++) {
      if (projected[i].id === id) {
        this.setState({
          projectedata: projected[i],
        })
      }
    }

    reGet(
      'https://licat.work/page_center/project/' + id + '/' + name,
      (data) => {
        // 防抖
        let { timer } = this.state
        if (timer === id + name) {
          this.setState({
            pagedata: data.data,
          })
        }
      },
    )
  }

  // 保存卡片数据，删除时获取id
  cardClick = ({ i }) => {
    this.setState({
      onepage: i,
    })
  }

  // 项目增加修改后更新state
  childChange = ({ projected, projectedata, punt, prod }) => {
    // 更新导航
    this.setState({
      projected: projected,
    })
    // 更新头部
    if (projectedata) {
      this.setState({
        projectedata: projectedata,
      })
    }
    // 请求默认页面(删除项目或跳转主页)
    if (punt) {
      this.setState({
        prod: prod,
        page: 'landingpage',
        timer: prod + 'landingpage',
      })
      reGet(
        'https://licat.work/page_center/project/' + prod + '/landingpage',
        (pagedata) => {
          let { timer } = this.state
          if (timer === prod + 'landingpage') {
            this.setState({
              pagedata: pagedata.data,
            })
          }
        },
      )
    }
  }

  // 更新某个页面卡片集合
  pageChange = ({ pagedata }) => {
    // 更新页面集合
    this.setState({
      pagedata: pagedata,
    })
  }

  // 项目弹窗
  inProject = ({ title, success, change }) => {
    const _$ = window.$
    const _layer = window.layer

    let index = _layer.open({
      type: 1,
      shade: 0.2,
      shadeClose: false,
      skin: 'proWind',
      content: _$('.proWindow'),
      title: title, //不显示标题
      btn: '提交',
      success: success,
      yes: function () {
        if (_$('#pro1').val() === '') {
          _$('#pro1').css('border-color', 'red')
          _layer.tips('请填写项目名称', _$('#pro1'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#pro2').val() === '') {
          _$('#pro2').css('border-color', 'red')
          _layer.tips('请填写指导老师', _$('#pro2'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#pro3').val() === '') {
          _$('#pro3').css('border-color', 'red')
          _layer.tips('请填写项目描述', _$('#pro3'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#pro4').val() === '') {
          _$('#pro4').css('border-color', 'red')
          _layer.tips('请填写关键字', _$('#pro4'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#pro5').val() === '') {
          _$('#pro5').css('border-color', 'red')
          _layer.tips('请填写头像路径', _$('#pro5'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#pro6').val() === '') {
          _$('#pro6').css('border-color', 'red')
          _layer.tips('请填写办公地点', _$('#pro6'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else {
          // 读取遍历信息
          let form = document.getElementById('myproject')
          let formdata = {}
          let oInp = form.querySelectorAll('#myproject input')
          for (let i = 0; i < oInp.length; i++) {
            if (oInp[i].name === 'photo') {
              i = i + 1
            }
            let name = oInp[i].name
            let value = oInp[i].value
            formdata[name] = value
          }
          change(index, formdata)
        }
      },
    })
    // 移动端弹窗全屏显示
    if (window.screen.width <= 750) {
      _layer.full(index)
    }
    _$('#myproject input').focus(function () {
      _$(this).removeAttr('style')
    })
  }

  // 落地页弹窗
  inLanding = ({ title, collect, change }) => {
    const _layer = window.layer
    const _$ = window.$
    const { prod } = this.state

    let index = _layer.open({
      type: 1,
      skin: 'landWind pageWind',
      shade: 0.3,
      title: title + '落地页',
      content: _$('.LandWindow'),
      btn: '提交',
      success: collect,
      // landingpage提交事件
      yes: function (index) {
        if (_$('#ss1').val() === '') {
          _$('#ss1').css('border-color', 'red')
          _layer.tips('请选择发布日期', _$('#ss1'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#ss2').val() === '') {
          _$('#ss2').css('border-color', 'red')
          _layer.tips('请填写作者', _$('#ss2'), {
            tips: [2, '#3595CC'],
            // time: 2000
          })
        } else if (_$('#ss4').val() === '') {
          _$('#ss4').css('border-color', 'red')
          _layer.tips('请填写页面标题', _$('#ss4'), {
            tips: [2, '#3595CC'],
            // time: 2000
          })
        } else if (_$('#ss6').val() === '') {
          _$('#ss6').css('border-color', 'red')
          _layer.tips('请填写页面描述', _$('#ss6'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#ss5').val() === '') {
          _$('#ss5').css('border-color', 'red')
          _layer.tips('请填写图片路径', _$('#ss5'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#ss8').val() === '') {
          _$('#ss8').css('border-color', 'red')
          _layer.tips('请填写html代码', _$('#ss8'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#eninput').val() === '') {
          _$('#eninput').css('border-color', 'red')
          _layer.tips('请输入加密代码', _$('#eninput'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (!_$('input:radio[name="grade"]:checked').val()) {
          _layer.tips('请选择页面评级', _$('#ss3'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (!_$('#ss7 input:radio[name="status"]:checked').val()) {
          _layer.tips('请选择发布状态', _$('#ss7'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else {
          // 读取输入信息
          let form1 = document.getElementById('ss3')
          let form2 = document.getElementById('ss7')
          let formdata = {}
          let oLab = form1.getElementsByTagName('input')
          let oLac = form2.getElementsByTagName('input')
          let oInp = document.querySelectorAll(
            '#landingform input,#landingform textarea',
          )
          for (let i = 0; i < oInp.length; i++) {
            if (oInp[i].name === 'photo') {
              i = i + 1
            }
            let name = oInp[i].name
            let value = oInp[i].value
            // 获取页面评级value值
            if (i < oLab.length) {
              if (oLab[i].checked) {
                formdata[oLab[i].name] = oLab[i].value
              }
            }
            // 获取发布状态value值
            if (i < oLac.length) {
              if (oLac[i].checked) {
                formdata[oLac[i].name] = Number(oLac[i].value)
              }
            }
            formdata[name] = value
          }
          formdata['projectid'] = prod
          change(index, formdata)
        }
      },
    })
    // 移动端弹窗全屏显示
    if (window.screen.width <= 750) {
      _layer.full(index)
    }
    _$('#landingform input,textarea').focus(function () {
      _$(this).removeAttr('style')
    })
  }

  // 审核页弹窗
  inaudit = ({ title, collect, change }) => {
    const _layer = window.layer
    const _$ = window.$
    const { prod } = this.state

    let index = _layer.open({
      type: 1,
      skin: 'auditWind pageWind',
      shade: 0.3,
      title: title + '审核页信息', //不显示标题
      content: _$('.AuditWindow'),
      btn: '提交',
      success: collect,
      yes: function (index) {
        if (_$('#ll1').val() === '') {
          _$('#ll1').css('border-color', 'red')
          _layer.tips('请选择发布日期', _$('#ll1'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#ll4').val() === '') {
          _$('#ll4').css('border-color', 'red')
          _layer.tips('请填写标题', _$('#ll4'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#ll5').val() === '') {
          _$('#ll5').css('border-color', 'red')
          _layer.tips('请填写图片路径', _$('#ll5'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (_$('#ll8').val() === '') {
          _$('#ll8').css('border-color', 'red')
          _layer.tips('请填写html代码', _$('#ll8'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else if (!_$('#ll7 input:radio[name="status"]:checked').val()) {
          _layer.tips('请选择发布状态', _$('#ll7'), {
            tips: [2, '#3595CC'],
            time: 2000,
          })
        } else {
          let form = document.getElementById('ll7')
          let formdata = {}
          let oLac = form.getElementsByTagName('input')
          let oInp = document.querySelectorAll(
            '#auditform input,#auditform textarea',
          )
          for (let i = 0; i < oInp.length; i++) {
            if (oInp[i].name === 'photo') {
              i = i + 1
            }
            let name = oInp[i].name
            let value = oInp[i].value
            // 获取发布状态value值
            if (i < oLac.length) {
              if (oLac[i].checked) {
                formdata[oLac[i].name] = Number(oLac[i].value)
              }
            }
            formdata[name] = value
          }
          formdata['projectid'] = prod
          change(index, formdata)
        }
        return false
      },
    })
    _$('#auditform input,textarea').focus(function () {
      _$(this).removeAttr('style')
    })
    // 移动端弹窗全屏显示
    if (window.screen.width <= 750) {
      _layer.full(index)
    }
  }

  // 卡片删除
  deletePage = (pageChange) => {
    const _layer = window.layer
    const { page, pagedata, onepage } = this.state
    _layer.confirm(
      '您确定要删除该页面吗？',
      {
        icon: 2,
        btn: ['确认', '取消'], //按钮
      },
      function () {
        // 发送删除请求
        reDelete({
          url: 'https://licat.work/page_center/' + page + '/' + onepage.id,
          // 删除state中的卡片
          Delete: function () {
            for (let i = 0; i < pagedata.length; i++) {
              if (pagedata[i].id === onepage.id) {
                pagedata.splice(i, 1)
              }
            }
            // 更新视图
            pageChange({ pagedata })
          },
        })
      },
    )
  }

  // html代码预览弹窗
  pageview = (page, e) => {
    const _layer = window.layer
    const _$ = window.$
    let val = e.target.value
    // 判断弹窗标题
    function tittext() {
      if (page === 'landingpage') {
        if (_$('#ss4').val()) {
          return _$('#ss4').val()
        } else {
          return '新的落地页'
        }
      } else if (page === 'auditpage') {
        if (_$('#ll4').val()) {
          return _$('#ll4').val()
        } else {
          return '新的审核页'
        }
      }
    }
    // 判断需要截屏按钮
    function needBtn() {
      if (window.screen.width <= 750 || e.target.id === 'eninput') {
        return '保存'
      } else {
        return ['保存', '截图']
      }
    }

    let index = _layer.open({
      type: 1,
      shade: 0.3,
      skin: 'layCode',
      shadeClose: false,
      maxmin: true,
      offset: 'auto',
      scrollbar: false,
      title: tittext(),
      btn: needBtn(),
      content: _$('.CodeWindow'),
      success: function () {
        if (val) {
          // html放到代码框
          _$('#tet').val(val)
          // 展示解密后的页面
          if (e.target.id === 'eninput') {
            _$('#vip').attr('srcdoc', uncompile(_$('#tet').val()))
          } else {
            _$('#vip').attr('srcdoc', _$('#tet').val())
          }
        }
      },
      yes: function (index) {
        // 审核页代码保存
        if (page === 'auditpage') {
          _$('#ll8').val(_$('#tet').val())
        } else {
          // 加密保存
          if (e.target.id === 'eninput') {
            _$('#eninput').val(_$('#tet').val())
          } else {
            // 源码及加密保存
            _$('#ss8').val(_$('#tet').val())
            _$('#eninput').val(compile(_$('#tet').val()))
          }
        }
        _layer.msg('保存成功', {
          time: 1000,
          icon: 1,
        })
      },
      btn2: function () {
        unit(rePhoto);
        return false
      },
      cancel: function (index) {
        if (page === 'auditpage') {
          // 判断审核页是否保存代码
          if (_$('#ll8').val() !== _$('#tet').val()) {
            _layer.confirm(
              '您还未保存代码，是否保存？',
              {
                btn: ['保存', '退出'], //按钮
                icon: 3,
              },
              function () {
                _$('#ll8').val(_$('#tet').val())
                _$('#tet').val('')
                _$('#vip').attr('srcdoc', '')
                _layer.close(_layer.index)
                _layer.msg('保存成功', {
                  time: 800,
                  icon: 1,
                })
                _layer.close(index)
              },
              function () {
                _layer.close(index)
                _$('#tet').val('')
                _$('#vip').attr('srcdoc', '')
              },
            )
          } else {
            _layer.close(index)
            _$('#tet').val('')
            _$('#vip').attr('srcdoc', '')
          }
        } else {
          // 判断加密代码是否保存
          if (
            e.target.id === 'eninput' &&
            _$('#eninput').val() !== _$('#tet').val()
          ) {
            _layer.confirm(
              '您还未保存加密代码，是否保存？',
              {
                btn: ['保存', '退出'], //按钮
                icon: 3,
              },
              function () {
                // 保存密码
                _$('#eninput').val(_$('#tet').val())
                // 清除代码防止重复截图
                _$('#tet').val('')
                _$('#vip').attr('srcdoc', '')
                // 关闭代码窗
                _layer.close(_layer.index)
                _layer.msg('保存成功', {
                  time: 800,
                  icon: 1,
                })
                _layer.close(index)
              },
              function () {
                _layer.close(index)
                _$('#tet').val('')
                _$('#vip').attr('srcdoc', '')
              },
            )
            // 判断源码是否保存
          } else if (
            e.target.id === 'ss8' &&
            _$('#ss8').val() !== _$('#tet').val()
          ) {
            _layer.confirm(
              '您还未保存代码，是否保存？',
              {
                btn: ['保存', '退出'], //按钮
                icon: 3,
              },
              function () {
                // 保存源码和密码
                _$('#ss8').val(_$('#tet').val())
                _$('#eninput').val(compile(_$('#tet').val()))
                // 清除代码防止重复截图
                _$('#tet').val('')
                _$('#vip').attr('srcdoc', '')
                // 关闭代码窗
                _layer.close(_layer.index)
                _layer.msg('保存成功', {
                  time: 800,
                  icon: 1,
                })
                _layer.close(index)
              },
              function () {
                // 清除代码防止重复截图
                _$('#tet').val('')
                _$('#vip').attr('srcdoc', '')
                _layer.close(index)
              },
            )
          } else {
            _layer.close(index)
            _$('#tet').val('')
            _$('#vip').attr('srcdoc', '')
          }
        }
        return false
      },
    })

    if (window.screen.width > 750) {
      // 代码监听同步iframe
      _$('#tet').bind('input propertychange', function () {
        if (e.target.id === 'eninput') {
          _$('#vip').attr('srcdoc', uncompile(_$('#tet').val()))
        } else {
          _$('#vip').attr('srcdoc', _$('#tet').val())
        }
      })
      // Ctrl+s保存
      _$('#tet').focus(() => {
        document.onkeydown = function (e) {
          if (e.ctrlKey) {
            if (e.key === 's') {
              // 阻止浏览器默认事件
              e.preventDefault()
              // 审核页保存
              if (page === 'auditpage') {
                _$('#ll8').val(_$('#tet').val())
              } else {
                if (e.target.id === 'eninput') {
                  _$('#eninput').val(_$('#tet').val())
                } else {
                  _$('#ss8').val(_$('#tet').val())
                  _$('#eninput').val(compile(_$('#tet').val()))
                }
              }
              _layer.msg('保存成功', {
                time: 1000,
                icon: 1,
              })
            }
          }
        }
      })
    } else {
      _layer.full(index)
    }
  }

  render() {
    const { prod, page, projected, pagedata, projectedata } = this.state
    return (
      <div className="Home">
        <Header
          prod={prod}
          projected={projected}
          projectedata={projectedata}
          inProject={this.inProject}
          cn={this.childChange}
        />
        <div className="main">
          <Nav
            prod={prod}
            page={page}
            projected={projected}
            fn={this.projClick}
            gn={this.firstClick}
            inProject={this.inProject}
            cn={this.childChange}
          />
          <Card
            prod={prod}
            page={page}
            projected={projected}
            pagedata={pagedata}
            inLanding={this.inLanding}
            inaudit={this.inaudit}
            cardClick={this.cardClick}
            pageChange={this.pageChange}
          />
          {/* 弹窗组件 */}
          {window.userpower && window.userpower === 7 ? (
            <>
              <ProWindow
                prod={prod}
                projected={projected}
                projectedata={projectedata}
                cn={this.childChange}
              />
              <LandWindow
                pageview={this.pageview}
                page={page}
                deletePage={this.deletePage}
                pageChange={this.pageChange}
              />
              <AuditWindow
                pageview={this.pageview}
                page={page}
                deletePage={this.deletePage}
                pageChange={this.pageChange}
              />
              <CodeWindow />
            </>
          ) : (
            <></>
          )}
          {/* 导航栏M端按钮 */}
          <NavSwitch />
        </div>
      </div>
    )
  }
}

export default Home
