// 获取当前时间
export default function nowDate(now){
    let date = new Date();
    let month,day;
    if(date.getMonth() < 10){
        month = "0" + (date.getMonth() + 1);
    }else{
        month = date.getMonth() + 1;
    }
    if(date.getDate() < 10){
        day = "0" + date.getDate();
    }else{
        day = date.getDate();
    }
    let ddd = date.getFullYear() + "-" + month + "-" + day;

    let result;
    // 区分是否需要精确时间
    if(now){
        let aaa = date.getHours() + ":" + date.getMinutes() + ":" + date.getSeconds();
        result = ddd.toString() + "\xa0" + aaa.toString();
    }else{
        result = ddd.toString();
    }

    return result
}