// import rePhoto from '../Request/rePhoto';
import React from 'react';

export default function AuditWindow(props) {
    const {pageview,page,deletePage,pageChange} = props
    // 上传图片
    // function upload(e){
    //     let file = e.target.files[0];
    //     // let punt = 0;
    //     rePhoto(file);
    // }

    return (
        <div className="AuditWindow pageWindow">
            <button className="delete" onClick={deletePage.bind(this,pageChange)}>删除页面</button>
            <form action="" id="auditform" autoComplete="off" className="pageform">
                <div className="formhead">发布日期:</div>
                <input type='date' id='ll1' name='releasedate' placeholder='输入发布日期' />
                <br />
                <div className="formhead">标 题:</div>
                <input type='text' id= 'll4' name='title' placeholder='输入页面标题' />
                <br />
                <div className="formhead dm">网站代码:</div>
                <textarea type='text' id= 'll8' name='html' placeholder='输入html代码' onClick={pageview.bind(this,page)}></textarea>
                <div id= 'll9'>
                    <div className='mediu'>
                        <div className='phh'>
                            <span>+</span>
                            {/* <input accept="image/png, image/jpeg, image/gif, image/jpg" type='file' id='tt' onChange={upload.bind(this)} className='layui-layer-input pho' name='photo' /> */}
                        </div>
                        <img className='ppp' id="ppImg" src='#' alt='' />
                    </div>
                    <div className="biao">
                        <p>图片大小<br />＜＝500KB</p>
                        <p>图片尺寸<br />＞＝320*568</p>
                    </div>
                </div>
                <div className="formhead">图片路径:</div>
                <input type='text' id='ll5' name='screenshot' placeholder='输入图片路径'/>
                <br />
            </form>
            <div id='ll7' className="single young">
                <div className="formhead fb">发布状态:</div>
                <div className="label_box">
                    <label>
                        <input type="radio" name="status" value="0" />
                        <div>未发布</div>
                    </label>
                    <label>
                        <input type="radio" name="status" value="1" />
                        <div>已发布</div>
                    </label>
                </div>
            </div>
        </div>
    )
}